_T_INT_OR_STR = TypeVar("_T_INT_OR_STR", int, str, covariant=False)


class ConfigurationManager:
    def __init__(self):
        self._tl_config = None
        self._additional_tl_config: dict = {}
        self.telemetry = get_telemetry_instance()
        self._user_flags: dict = {}
        self._output_directory: str = ""
        self._host_runners: dict = {}
        self._wtssim_instance: wtssim = wtssim()
        self._wts_config_file_path: str = ""
        self._suite_config_dir: str = ""
        self._config_call_counter: int = 1
        self._load_config()
        configure_env_configurator_loggers(self._output_directory, self._config_call_counter)
        self.logger: logging.Logger = logging.getLogger(PACKAGE_NAME)
        self.logger_recovery: logging.Logger = logging.getLogger(RECOVERY_LOG_NAME)
        self._create_env_configuration()

    @property
    def tl_config(self) -> UTE_CONFIG | TestLine:
        if not self._tl_config:
            tl_config, additional_tl_config = get_ute_tl_config()
            self._tl_config = tl_config
            self._additional_tl_config = additional_tl_config
        return self._tl_config

    @property
    def additional_tl_config(self) -> dict:
        if not self._additional_tl_config:
            tl_config, additional_tl_config = get_ute_tl_config(self.logger)
            self._tl_config = tl_config
            self._additional_tl_config = additional_tl_config
        return self._additional_tl_config

    @cached_property
    def wts_config_data(self):
        tl_config = self._prepare_wts_config()
        self.logger.debug(pformat(tl_config))
        cus_yaml = self._user_flags.get("cus_yaml")
        if cus_yaml:
            config = self._read_yaml_file(cus_yaml)
            self.logger.debug(pformat(config))
            yaml_wts_config = self._set_epc_conf_from_yaml(config)
            self.logger.debug(pformat(yaml_wts_config))
            tl_config.update(yaml_wts_config)
        self._verify_mandatory_wts_params(tl_config)
        self.logger.debug(pformat(tl_config))
        return tl_config

    @property
    def _wtssim_alias(self) -> str:
        return self.wts_config_data["wtssim_alias"]

    def _update_cus_yaml(self, cus_yaml):
        self._user_flags.update({"cus_yaml": cus_yaml})
        for host_id in self._config:
            if not host_id.isdigit():
                continue
            if DevicesNames.CUS in self._config[host_id]:
                self._config[host_id][DevicesNames.CUS]["file"] = cus_yaml

    def _has_sim(self):
        if any(dev in DevicesNames for k, v in self._config.items() if k.isdigit() for dev in v):
            return True
        return False

    def _run_coco_cus_config_generator_if_cus_yaml(self):
        cus_yaml = self._user_flags.get("cus_yaml")

        if not cus_yaml:
            return

        # TODO: Remove WA after fix for wrong java version delivered
        cmd = (
            "sudo -u cus "
            + "/opt/cus/lib/jdk/bin/java "
            + "-cp /opt/cus/lib/executor/executor.jar:/opt/cus/lib/executor/snakeyaml-1.29.jar:"
            + "/opt/cus/lib/executor/OtpErlang.jar:/opt/cus/lib/executor/jsch-0.2.11.jar "
            + "com.nok.executor.util.config.Config generate_config {}"
        )

        master_node_addr = self._get_master_node_addr()
        cus_node_addr = self._get_cus_node_addr()
        self.logger.debug(f"MASTER_NODE_ADDR={master_node_addr}, CUS_NODE_ADDR={cus_node_addr}")
        if master_node_addr and cus_node_addr and master_node_addr != cus_node_addr:
            coco_yaml = "/tmp/coco.yaml"
            epc_cfg = "/tmp/config.cfg"
            cmd = cmd.format(coco_yaml)
            execute_sudo_command(f"cp {cus_yaml} {coco_yaml}", self.logger)
            upload_to_remote(cus_node_addr, coco_yaml, coco_yaml, self.logger)
            execute_remote_sudo_command(cus_node_addr, cmd, self.logger)
            download_from_remote(cus_node_addr, epc_cfg, epc_cfg, self.logger)
            self._update_cus_yaml(coco_yaml)
        else:
            cmd = cmd.format(cus_yaml)
            execute_sudo_command(cmd, self.logger)

    def _get_master_node_addr(self):
        try:
            for host_id in sorted(self.host_runners.keys()):
                host_runner = self.host_runners[host_id]
                return host_runner.remote_host
        except Exception as exc:
            self.logger.debug(f"Cannot get master node address: {exc}")
        return None

    def _get_cus_node_addr(self):
        for host_id in sorted(self.host_runners.keys()):
            host_runner = self.host_runners[host_id]
            if host_runner.has_cus():
                return host_runner.remote_host
        return None

    def _is_wts_started_locally(self):
        server_host = get_ip_address("eth0")
        return self.wts_config_data["host_ip"] in ("127.0.0.1", server_host)

    def _verify_mandatory_wts_params(self, config):
        wtssim_alias = self._user_flags["wtssim_alias"]
        defaults = {
            "host_ip": "127.0.0.1",
            "tool_dir": self._user_flags.get("tool_dir"),
            "egate_port": 20000,
            "edaemon_ports": self._user_flags.get("edaemon_ports"),
            "ssh_username": "ute",
            "ssh_password": "ute",
            "wtssim_alias": "config" if wtssim_alias is None else None if wtssim_alias == "default" else wtssim_alias,
        }
        for k, v in defaults.items():
            if k not in config:
                config[k] = v

    def _set_epc_conf_from_yaml(self, config):
        ret_conf = {}
        try:
            epc_conf = {k.lower(): v for k, v in config["EPC"]["WS"][0].items()}
            wts_path = self._get_value_or_false(epc_conf, "wts_path") or DEFAULT_COCO_WTS_PATH
            edaemon_ports = self._get_value_or_false(epc_conf, "edaemon_port") or DEFAULT_4G_EDAEMON_PORTS
            edaemon_ports = tuple(edaemon_ports) if isinstance(edaemon_ports, (list, tuple)) else (int(edaemon_ports),)
            edaemon_ip = self._get_value_or_false(epc_conf, "edaemon_ip") or DEFAULT_COCO_EGATE_IP
            for k, v in [
                ("tool_dir", wts_path),
                ("edaemon_ports", edaemon_ports),
                ("host_ip", edaemon_ip),
            ]:
                ret_conf.update({k: v} if v else {})
        except KeyError:
            pass
        return ret_conf

    @staticmethod
    def _get_value_or_false(_dict, param):
        return _dict.get(param, False)

    @property
    def host_runners(self) -> dict[int, HostConfigurator]:
        """

        :return:
        """
        if not self._host_runners:
            self._configure_host_runners()
            self.logger.debug("Host runners created.")
        return self._host_runners

    def get_devices(self) -> list[dict[str, list]]:
        """

        :return:
        """
        devices = [host_runner.get_devices() for host_runner in self._host_runners.values()]
        return devices

    def _prepare_wts_config(self) -> dict[str, str | int]:
        if self.additional_tl_config:
            core_con = self.additional_tl_config["core"]
            workstation = core_con["workstation"]
            return {
                "tool_dir": core_con["epcsim_dir"],
                "ssh_username": workstation["login"],
                "ssh_password": workstation["password"],
                "ssh_root_password": workstation["root_password"],
                "host_ip": workstation["host"],
                "egate_port": core_con["cli"]["port"],
            }
        return {}

    def start_wts_services_and_configure_egate(self, validate=True, max_attempts=3, optional=False):
        # type: (bool, int, bool) -> None
        """
        Start, configure and activate WTS environment.
        :param bool validate: validate EPC/eNB/SIM after activation.
        :param int max_attempts: maximum number of attempts to start/configure
        :param bool optional: do not fail if cannot start EPC.
        :return:
        :raise Exception: If couldn't get EGATE to ACTIVE state or validation of eNB or SIM fails
        """
        self.logger.debug("start_wts_services_and_configure_egate")
        egate_active_timeout = int(self._user_flags.get("egate_timeout", 10 * 60))
        for attempt in range(max_attempts):
            try:
                start_time = time.time()
                self._start_wts_apps_and_services()
                if validate:
                    self._validate(start_time, egate_active_timeout)
                return
            except Exception as err:
                self.logger.debug(err, exc_info=True)
                self.logger_recovery.info(err)
                self._check_egate_status()
                self._teardown_wts()
                self._log_esim_processes_info()
                if not optional:
                    if attempt < max_attempts - 1:
                        self._start_action_on_nodes("reset_devices_and_wait_for_sync")
                    else:
                        raise

    def _log_esim_processes_info(self):
        get_esim_procs(self.logger)
        get_netstat(self.logger)

    def _validate(self, start_time, max_timeout):
        self._validate_epc_active(get_time_diff(start_time, max_timeout))
        self._validate_bts(get_time_diff(start_time, max_timeout))
        self._validate_sim(get_time_diff(start_time, max_timeout))

    def _validate_epc_active(self, timeout):
        check_version = self._user_flags.get("check_wts_version", True)
        ensure_all_components_are_activated(timeout, self._wtssim_instance, self._wtssim_alias, self.logger, check_version)

    def _check_egate_status(self):
        check_version = self._user_flags.get("check_wts_version", True)
        try:
            ensure_all_components_are_activated(2, self._wtssim_instance, self._wtssim_alias, self.logger, check_version)
        except Exception as err:
            self.logger.debug(err)

    def _start_wts_apps_and_services(self) -> None:
        epc_config_file = self._wts_config_file_path
        if not self._is_wts_started_locally():
            self.logger.debug(f"Configuring WTS according to conf: {self.wts_config_data}")
            epc_config_file = self._copy_epc_file_to_remote_machine()
            self.logger.debug(f"WTS Config file path: {epc_config_file}")
            self._wtssim_instance.configure_ssh_connection_for_wts(alias=self._wtssim_alias, **self.wts_config_data)
            self.logger.debug("WTS remotely configured")
        self.logger.info("Starting WTS applications and loading configuration file.")
        self.logger.debug("cfg_file = {}, wtssim_alias = {}, wts_config_data = {}".format(epc_config_file, self._wtssim_alias, self.wts_config_data))
        if self._wtssim_alias not in self._wtssim_instance.wts_aliases:
            execute_sudo_command(f"chown ute:ute {self.wts_config_data['tool_dir']}", self.logger)
            self._wtssim_instance.start_wts_applications(cfg_file=epc_config_file, timeout="60s", alias=self._wtssim_alias, **self.wts_config_data)
            sleep(1)
        check_version = self._user_flags.get("check_wts_version", True)
        self._wtssim_instance.execute_egate_command(
            "start version_check={}".format("on" if check_version else "off"),
            alias=self._wtssim_alias,
        )

    def _teardown_wts(self) -> None:
        try:
            self._wtssim_instance.stop_and_collect_wts_logs(alias=self._wtssim_alias)
        except Exception as err:
            self.logger.debug(err, exc_info=True)

    def configure_environment(self) -> None:
        """

        :return:
        """
        if self._has_sim() and self._wts_config_file_path:
            self._run_coco_cus_config_generator_if_cus_yaml()
            self.start_wts_services_and_configure_egate(validate=False, max_attempts=2, optional=True)
        self._start_action_on_nodes("precondition_for_full_rack")
        self._start_action_on_nodes("configure_simulators")
        self._start_action_on_nodes("configure_btses")
        hosts_barrier = Barrier(len(self.host_runners))
        self._start_action_on_nodes("wait_for_devices_to_sync", hosts_barrier)
        if self._wts_config_file_path:
            self.start_wts_services_and_configure_egate()
        self.logger.info("ConfigurationManager finished successfully!")

    def validate_simulators(self):
        self._configure_host_runners()
        self._wtssim_instance.setup_egate(
            self.wts_config_data.get("egate_port"),
            self.wts_config_data.get("host_ip"),
            self.wts_config_data.get("tool_dir"),
            alias=self._wtssim_alias,
        )
        if self.wts_config_data:
            self._wtssim_instance.configure_ssh_connection_for_wts(alias=self._wtssim_alias, **self.wts_config_data)
        self._validate_sim(120)

    @overload
    def _start_action_on_nodes(self, action: str) -> None: ...

    @overload
    def _start_action_on_nodes(self, action: str, timeout: float) -> None: ...

    @overload
    def _start_action_on_nodes(self, action: str, barrier: Barrier) -> None: ...

    def _start_action_on_nodes(self, action, *args, **kwargs) -> None:
        self.logger.debug(f"{action = }, {args = }, {kwargs = }")
        if not self.host_runners:
            self.logger.info("No hosts found, no remote config will be executed.")
            return
        exception_caught = None
        funcs = [getattr(host_runner, action) for host_runner in self.host_runners.values()]
        futures = []
        with ThreadPoolExecutor(max_workers=len(self.host_runners)) as executor:
            for function in funcs:
                future = executor.submit(function, *args)
                futures.append(future)
            try:
                for future in as_completed(futures, timeout=60 * 60 * 3):
                    future.result()
            except Exception as err:
                # todo  get err for all futures not just 1st one.
                self.logger.warning(err, exc_info=True)
                exc_type, exc_value, exc_tb = sys.exc_info()
                exception_caught = exc_type, exc_value, exc_tb
        self.check_exception_and_reraise_if_needed(exception_caught)

    def _create_env_configuration(self) -> None:
        self.logger.debug(self.tl_config)
        self.logger.debug(self.additional_tl_config)
        assert isinstance(self.tl_config, taf.config.testline.TestLine), "Only TAF configuration is supported"
        sims_names = [type(ue).__name__.lower() for ue in self.tl_config.ues]
        self.logger.info(f"Detected simulators: {sims_names}")
        self.master_host_ip = get_ip_address("eth0")

    def check_exception_and_reraise_if_needed(
        self,
        exception_caught: Optional[tuple[Optional[type[BaseException]], Optional[BaseException], Optional[TracebackType]]],
    ) -> None:
        if exception_caught and isinstance(exception_caught[1], BaseException):
            self.logger.warning(f"{exception_caught = }")
            raise exception_caught[1]

    def _configure_host_runners(self) -> None:
        config_type = "ute" if isinstance(self.tl_config, UTE_CONFIG) else "taf"
        for host_id, node_config in prepare_config_for_tl(self.tl_config).items():
            configurator = HostConfigurator(
                host_id,
                node_config,
                self.master_host_ip,
                self._user_flags,
                config_type,
            )
            configurator.create_devices()
            configurator.update_configuration_paths(
                output_directory_path=self._output_directory,
                suite_config_dir=self._suite_config_dir,
            )
            self._host_runners[host_id] = configurator

    def _update_configurator_config_paths(self):
        """To make sure all the devices created in the meantime have the properly set dirs"""
        self.logger.debug("Updating configuration paths for all devices")
        for host_runner in self.host_runners.values():
            host_runner.update_configuration_paths(
                output_directory_path=self._output_directory,
                suite_config_dir=self._suite_config_dir,
            )

    def _load_config(self) -> None:
        with self.telemetry.trace("load_config") as load_config_trace:
            with Path(TMP_DIR, CONFIG_FILE).open("r") as config_file_opened:
                self._config = json.load(config_file_opened)
            self._trace_devices_for_telemetry(load_config_trace)
            out = {"label": self._get_tl_label(load_config_trace)}
            self.telemetry.update("execution_details", 1, out)
            self._set_additional_config_params()
            if opt_bool(self._user_flags.get("dryrun", False)):
                result = {"status": "SUCCESS", "info": "DRYRUN"}
                save_result(result)
                sys.exit(0)

    @staticmethod
    def _get_tl_label(trace_object: Span) -> str:
        tl_label = get_tl_label_from_common_agent_log() or "unknown"
        if tl_label == "unknown":
            trace_object.set_attributes({"tree": pformat(get_tree_output()), "env": pformat(get_env_output()), "label": tl_label})
        return tl_label

    def _trace_devices_for_telemetry(self, trace_object: Span):
        if isinstance(self.tl_config, UTE_CONFIG):
            tl_type = "4G"
        else:
            if self.tl_config.enbs and not self.tl_config.gnbs:
                tl_type = "4G"
            elif self.tl_config.gnbs and not self.tl_config.enbs:
                tl_type = "5G"
            elif self.tl_config.enbs and self.tl_config.gnbs:
                tl_type = "4G/5G"
            else:
                tl_type = "unknown"
        trace_object.set_attributes({"tl_type": tl_type, "tl_name": os.uname().nodename})

    def _set_cloud_scfcs(self, cbts: CloudBTS, cbts_conf: CloudBTSDictType, cbts_id: int, host_id: int) -> None:
        cbts.vcu_scfc_names = cbts_conf["vcu_scfc"]
        cbts.vdu_scfc_names = cbts_conf["vdu_scfc"]
        self.logger.debug(f"Setting SCFCs for bts-{cbts_id} on host-{host_id}." f" {cbts_conf['vcu_scfc'] = };**;{cbts_conf['vdu_scfc'] = }")

    def _set_bts_param(self, bts: BTS, bts_conf: BTSDictType, bts_id: int, host_id: int, param_name: str) -> None:
        if param_name not in bts_conf:
            return
        params = bts_conf[param_name]  # type: ignore
        self.logger.debug(f"set {param_name} for bts [{params}] for bts-{bts_id} on host-{host_id}")
        setattr(bts, param_name, params)

    def _set_scfc(self, bts: BTS, bts_conf: BTSDictType, bts_id: int, host_id: int) -> None:
        if "scfc" in bts_conf:
            scfc_path = bts_conf["scfc"]
            self.logger.debug(f"Setting SCFC [{scfc_path}] for bts-{bts_id} on host-{host_id}")
            bts.scfc_name = scfc_path
            bts.set_commissioning_timeout(bts_conf["COMMISSIONING_TIMEOUT"])  # todo: change BTSDictType to Enums

    def _set_full_rack_details(self, bts: BTS, bts_conf: BTSDictType, bts_id: int, host_id: int) -> None:
        if bts_conf["secondary"] is True:
            bts.set_bts_as_secondary_for_full_rack()
            self.logger.debug(f"Setting bts-{bts_id} on host-{host_id} as secondary for full-rack configuration")
        elif bts_conf["primary"] is True:
            bts.set_bts_as_primary_for_full_rack()
            self.logger.debug(f"Setting bts-{bts_id} on host-{host_id} as primary for full-rack configuration")

    def _read_yaml_file(self, yaml_file):
        try:
            with open(yaml_file) as yml_fh:
                data = yaml.load(yml_fh, Loader=yaml.FullLoader)
        except (yaml.YAMLError, TypeError):
            self.logger.error("Error in yaml file, couldn't load it to parse.")
            raise
        return data

    def _set_wts_config_file_path(self) -> None:
        wts_config = self.__get_param_from_config("wts")
        self._wts_config_file_path = wts_config.get(CFG_WTS.CONFIG_FP, None)
        self.logger.debug(f"Set WTS config file path: '{self._wts_config_file_path}'")

    def _set_device_config(self, device_name: DevicesNames, device_conf: list, host_id: int) -> None:
        for device_id, device_config in enumerate(device_conf, start=1):
            self.logger.info(f"Creating device {device_name}-{device_id} on host-{host_id}")
            device = self.host_runners[host_id].get_device(device_id, device_name)
            self.__set_device_config(device, host_id, device_config, device_id)

    @singledispatchmethod
    def __set_device_config(self, *args, **kwargs):
        raise NotImplementedError(f"Device of such type not supported. This is rather internal bug, please report it.\n{args = }, {kwargs = }")

    @__set_device_config.register(BTS)
    def _(self, bts: BTS, host_id: int, bts_config: BTSDictType, bts_id: int):
        self._set_scfc(bts, bts_config, bts_id, host_id)
        self._set_full_rack_details(bts, bts_config, bts_id, host_id)
        for param_name in [key for key in bts_config.keys() if key.endswith("_params")]:
            self._set_bts_param(bts, bts_config, bts_id, host_id, param_name)

    @__set_device_config.register(CloudBTS)
    def _(self, cloud_bts: CloudBTS, host_id: int, cloud_bts_config: CloudBTSDictType, cloud_bts_id: int):
        self._set_cloud_scfcs(cloud_bts, cloud_bts_config, cloud_bts_id, host_id)

    @__set_device_config.register(AirPhone)
    @__set_device_config.register(Iphy)
    def _(self, simulator: AirPhone | Iphy, host_id: int, simulator_config: SimulatorDictType, simulator_id: int):
        sim_xml = simulator_config["file"]
        self.logger.debug(f"set_{type(simulator).__name__}_xml [{sim_xml}] for sim-{simulator_id} on host-{host_id}")
        simulator.set_xml_path(sim_xml)
        simulator.connected_bts_id = simulator_config["connected_bts_id"]

    @__set_device_config.register(CUS)
    def _(self, cus: CUS, host_id: int, cus_config: SimulatorDictType, cus_id: int):
        self.logger.debug(f"Set CUS config [{cus_config}] for CUS-{cus_id} on host-{host_id}")
        cus.set_config(cus_config)
        cus.connected_bts_id = int(cus_config["connected_bts_id"])
        if cus_config["api"] == SimConfigType.CUS_YAML:
            self._wts_config_file_path = Path(TMP_DIR, EPC_CONFIG_IF_YAML).as_posix()

    def set_configuration(self) -> None:
        """

        :return:
        """
        self.logger.info(f"CONFIG:\n{pformat(self._config)}")
        self._set_wts_config_file_path()
        self.logger.info(f"Output directory = {self._output_directory}")
        for host_id, node_data in self._config.items():
            try:
                host_id = int(host_id)
            except ValueError as err:
                self.logger.debug(err)
                continue
            self.logger.debug(f"{host_id = }, node_data = \n{pformat(node_data)}")
            for device_name, device_conf in node_data.items():
                self._set_device_config(device_name, device_conf, host_id)
        self._update_configurator_config_paths()

    def _set_additional_config_params(self):
        for param, value in self._config["user_config_params"].items():
            self._user_flags[param] = value
        for param, value in self._config["additional_config_params"].items():
            setattr(self, f"_{param}", value)

    def __get_param_from_config(self, param):
        try:
            return self._config.pop(param)
        except KeyError:
            return {}

    def _set_suite_config_dir(self) -> None:
        self._suite_config_dir = self._config.pop("suite_config_dir")

    def _validate_bts(self, timeout: float) -> None:
        if self._user_flags["validate_enb"] or self._user_flags["validate_gnb"] or self._user_flags["validate_cloud_bts"]:
            self._start_action_on_nodes("validate_bts", timeout)

    def _validate_sim(self, timeout: float) -> None:
        if not opt_bool(self._user_flags.get("validate_sim", True)):
            return
        start_time = time.time()
        devices = []
        for host_runner in self.host_runners.values():
            for sim in host_runner.get_devices()["simulator"]:
                devices.append(0 if sim.name in (DevicesNames.CUS, DevicesNames.RTG) else 1)
        if all(devices):
            self._validate_iphy_or_airphone(get_time_diff(start_time, timeout))
        elif not any(devices):
            self._validate_cus(get_time_diff(start_time, timeout))
        else:
            self.logger.warning("Mixed mode simulators detected. Cannot properly validate simulators state")

    def _validate_iphy_or_airphone(self, timeout: float) -> None:
        start_time = time.time()
        while (time.time() - start_time) < timeout:
            try:
                return ensure_sibs_are_received_on_each_cell_with_iphy_or_airphone(self._wtssim_instance, self._wtssim_alias, self.logger)
            except Exception as err:
                self.logger.debug(err)
                sleep(1)
        else:
            raise Exception("Validation on Iphy has failed within timeout.")

    def _validate_cus(self, timeout: float) -> None:
        for sim in self.host_runners[1].get_devices()["simulator"]:  # todo get proper host_runner
            if isinstance(sim, CUS):
                sim.ensure_sibs_are_received(timeout)

    def _copy_epc_file_to_remote_machine(self) -> str:
        with get_sftp_connection(
            self.logger,
            self.wts_config_data["host_ip"],
            22,
            self.wts_config_data["ssh_username"],
            self.wts_config_data["ssh_password"],
        ) as sftp:
            epc_config_file_path = Path(self._wts_config_file_path)
            new_epc_config_name = Path("/tmp", f"MODIFIED_{epc_config_file_path.name}").as_posix()
            sftp.put(self._wts_config_file_path, new_epc_config_name)
            return new_epc_config_name


def save_result(result: dict) -> None:
    with Path(TMP_DIR, RESULT_FILE).open("w") as result_file:
        json.dump(result, result_file, indent=4)


def _wait_for_logs_to_be_sent_and_collected() -> None:
    sleep(5)


configure_actions = [
    ConfigurationManager.set_configuration,
    ConfigurationManager.configure_environment,
]
validate_actions = [ConfigurationManager.validate_simulators]

CM_ACTIONS = {"configure": configure_actions, "validate": validate_actions}


def start_configuration(start_args: dict) -> None:
    result: dict = {"info": {}, "status": ""}
    try:
        cfg = ConfigurationManager()
        for action in CM_ACTIONS[start_args["start_mode"]]:
            action(cfg)
        result["status"] = "SUCCESS"
    except Exception:
        exc_info = sys.exc_info()
        result["status"] = "FAILURE"
        exc_info_formatted = "".join(traceback.format_exception(*exc_info))
        result["info"] = {
            "type": type(exc_info[1]).__name__,
            "message": str(exc_info[1]),
            "tb": exc_info_formatted,
        }
        try:
            logger = logging.getLogger(PACKAGE_NAME)
            logger.exception(exc_info_formatted)
        except (AttributeError, NameError):
            pass
    finally:
        _wait_for_logs_to_be_sent_and_collected()
    save_result(result)
    metadata = {
        "version": get_version(PACKAGE_NAME),
        "status": result["status"],
        "type": result["info"].get("type", ""),
        "msg": result["info"].get("message", ""),
    }
    get_telemetry_instance().update("configurator_execution", 1, metadata)


def validate_start_args():
    start_mode = sys.argv[1]
    assert start_mode in (
        "configure",
        "validate",
    ), "Wrong start mode. Possible: [configure, validate]"
    return {"start_mode": start_mode}


if __name__ == "__main__":
    sys.argv.append("configure")
    start_args = validate_start_args()
    start_configuration(start_args)
